import gurobipy as gp
from gurobipy import GRB

def main():
    env = gp.Env()
    env.start()
    model = gp.Model(env=env)

    workers = ['I', 'II', 'III', 'IV', 'V']
    tasks = ['A', 'B', 'C', 'D']
    time = {
        'I':   {'A': 9, 'B': 4, 'C': 3, 'D': 7},
        'II':  {'A': 4, 'B': 6, 'C': 5, 'D': 6},
        'III': {'A': 5, 'B': 4, 'C': 7, 'D': 5},
        'IV':  {'A': 7, 'B': 5, 'C': 2, 'D': 3},
        'V':   {'A':10, 'B': 6, 'C': 7, 'D': 4}
    }

    x = {}
    for i in workers:
        for j in tasks:
            x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

    model.update()

    # each task assigned to exactly one worker
    for j in tasks:
        model.addConstr(gp.quicksum(x[i, j] for i in workers) == 1, name=f"task_{j}")

    # each worker at most one task
    for i in workers:
        model.addConstr(gp.quicksum(x[i, j] for j in tasks) <= 1, name=f"worker_{i}")

    # objective: minimize total time
    model.setObjective(
        gp.quicksum(time[i][j] * x[i, j] for i in workers for j in tasks),
        GRB.MINIMIZE
    )

    model.optimize()

    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.objVal}")

if __name__ == "__main__":
    main()
