import gurobipy as gp
from gurobipy import GRB

def main():
    # Processing times t_{ij}
    t = {
        1: {1: 2, 2: 3, 3: 1},
        2: {1: 4, 2: 2, 3: 3},
        3: {1: 3, 2: 5, 3: 2}
    }

    jobs = [1, 2, 3]
    machines = [1, 2, 3]
    positions = [1, 2, 3]

    M_order = 3   # big‑M for ordering constraints
    M_prec  = 100 # big‑M for precedence constraints

    # Create model with the provided environment
    m = gp.Model(env=env)

    # Decision variables
    x = m.addVars(jobs, positions, vtype=GRB.BINARY, name="x")   # job i at position k
    y = m.addVars(jobs, jobs, vtype=GRB.BINARY, name="y")       # y[i,h] = 1 if i precedes h
    C = m.addVars(jobs, machines, vtype=GRB.CONTINUOUS, name="C")# completion times
    Cmax = m.addVar(vtype=GRB.CONTINUOUS, name="Cmax")           # makespan

    # Each job is assigned to exactly one position
    for i in jobs:
        m.addConstr(gp.quicksum(x[i, k] for k in positions) == 1)

    # Each position is assigned to exactly one job
    for k in positions:
        m.addConstr(gp.quicksum(x[i, k] for i in jobs) == 1)

    # Precedence variables: for each pair of distinct jobs
    for i in jobs:
        for h in jobs:
            if i != h:
                m.addConstr(y[i, h] + y[h, i] == 1)

    # Ordering constraints linking positions and precedence variables
    for i in jobs:
        for h in jobs:
            if i != h:
                pos_i = gp.quicksum(k * x[i, k] for k in positions)
                pos_h = gp.quicksum(k * x[h, k] for k in positions)
                m.addConstr(pos_i - pos_h <= -1 + M_order * (1 - y[i, h]))

    # Flow‑shop constraints: each job must finish on machine j after finishing on j‑1
    for i in jobs:
        m.addConstr(C[i, 1] >= t[i][1])  # start on machine 1 at time 0
        for j in machines[1:]:
            m.addConstr(C[i, j] >= C[i, j - 1] + t[i][j])

    # Precedence constraints on each machine
    for i in jobs:
        for h in jobs:
            if i != h:
                for j in machines:
                    m.addConstr(C[h, j] >= C[i, j] + t[h][j] - M_prec * (1 - y[i, h]))

    # Makespan constraints
    for i in jobs:
        m.addConstr(Cmax >= C[i, 3])

    # Objective: minimize makespan
    m.setObjective(Cmax, GRB.MINIMIZE)

    # Optimize
    m.optimize()

    # Output the optimal objective value
    if m.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={m.objVal}")

if __name__ == "__main__":
    main()
