import gurobipy as gp
from gurobipy import GRB

def main():
    model = gp.Model(env=env)

    # Parameters
    a = {1: 100, 2: 150}
    b = {1: 80, 2: 120}
    f = {1: 10, 2: 15}
    q = {1: 100, 2: 100}
    c = {(1, 1): 2, (1, 2): 3, (2, 1): 4, (2, 2): 1}
    c_prime = {(1, 1): 3, (1, 2): 2, (2, 1): 1, (2, 2): 4}

    # Decision variables
    x = {}
    for i in [1, 2]:
        for k in [1, 2]:
            for j in [1, 2]:
                x[i, k, j] = model.addVar(vtype=GRB.CONTINUOUS, lb=0,
                                           name=f"x_{i}_{k}_{j}")

    y = {}
    for k in [1, 2]:
        y[k] = model.addVar(vtype=GRB.BINARY, name=f"y_{k}")

    model.update()

    # Supply constraints
    for i in [1, 2]:
        model.addConstr(
            gp.quicksum(x[i, k, j] for k in [1, 2] for j in [1, 2]) <= a[i],
            name=f"supply_{i}"
        )

    # Demand constraints
    for j in [1, 2]:
        model.addConstr(
            gp.quicksum(x[i, k, j] for i in [1, 2] for k in [1, 2]) == b[j],
            name=f"demand_{j}"
        )

    # Capacity constraints
    for k in [1, 2]:
        model.addConstr(
            gp.quicksum(x[i, k, j] for i in [1, 2] for j in [1, 2]) <= q[k] * y[k],
            name=f"capacity_{k}"
        )

    # Objective
    transport_cost = gp.quicksum(
        (c[i, k] + c_prime[k, j]) * x[i, k, j]
        for i in [1, 2] for k in [1, 2] for j in [1, 2]
    )
    fixed_cost = gp.quicksum(f[k] * y[k] for k in [1, 2])
    model.setObjective(transport_cost + fixed_cost, GRB.MINIMIZE)

    # Solve
    model.optimize()

    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.ObjVal}")

if __name__ == "__main__":
    main()
