# Processing times matrix: rows = jobs (0..4), columns = machines (0..2)
p = [
    [3.0, 1.0, 1.0],
    [2.0, 1.5, 1.0],
    [3.0, 1.2, 1.3],
    [2.0, 2.0, 2.0],
    [2.1, 2.0, 3.0]
]

n_jobs = 5
n_machines = 3
M = 100.0  # Big-M constant

model = gp.Model(env=env)

# Start time variables s[i][j]
s = {}
for i in range(n_jobs):
    for j in range(n_machines):
        s[i, j] = model.addVar(lb=0.0, name=f"s_{i}_{j}")

# Makespan variable
Cmax = model.addVar(lb=0.0, name="Cmax")

# Binary ordering variables y[i][k][m] for i != k
y = {}
for i in range(n_jobs):
    for k in range(n_jobs):
        if i == k:
            continue
        for m in range(n_machines):
            y[i, k, m] = model.addVar(vtype=GRB.BINARY, name=f"y_{i}_{k}_{m}")

# Sequencing constraints on each machine
for m in range(n_machines):
    for i in range(n_jobs):
        for k in range(n_jobs):
            if i == k:
                continue
            # y[i][k][m] + y[k][i][m] == 1 for i < k
            if i < k:
                model.addConstr(y[i, k, m] + y[k, i, m] == 1, name=f"order_{i}_{k}_{m}")

            # Disjunctive constraints
            model.addConstr(
                s[i, m] >= s[k, m] + p[k][m] - M * (1 - y[i, k, m]),
                name=f"disc1_{i}_{k}_{m}"
            )
            model.addConstr(
                s[k, m] >= s[i, m] + p[i][m] - M * y[i, k, m],
                name=f"disc2_{i}_{k}_{m}"
            )

# Job precedence constraints (each job must finish on machine j before starting on j+1)
for i in range(n_jobs):
