model = gp.Model(env=env)

# Define data for each store type
store_data = {
    1: {'area': 250, 'k': [1, 2, 3], 'profit': {1: 9, 2: 8, 3: 7}},
    2: {'area': 350, 'k': [1, 2],     'profit': {1: 10, 2: 9}},
    3: {'area': 800, 'k': [1, 2, 3], 'profit': {1: 27, 2: 21, 3: 20}},
    4: {'area': 400, 'k': [0, 1, 2], 'profit': {0: 0, 1: 16, 2: 10}},
    5: {'area': 500, 'k': [1, 2, 3], 'profit': {1: 17, 2: 15, 3: 12}}
}

# Create binary variables y_{i}_{k} indicating that type i has k stores
y = {}
for i, data in store_data.items():
    for k in data['k']:
        y[(i, k)] = model.addVar(vtype=GRB.BINARY, name=f"y_{i}_{k}")

# Constraint: exactly one scenario per store type
for i, data in store_data.items():
    model.addConstr(gp.quicksum(y[(i, k)] for k in data['k']) == 1, name=f"one_scenario_{i}")

# Area constraint
model.addConstr(
    gp.quicksum(
        data['area'] * k * y[(i, k)]
        for i, data in store_data.items()
        for k in data['k']
    ) <= 5000,
    name="total_area"
)

# Objective: maximize total rental income (20% of total profit)
model.setObjective(
    0.2 * gp.quicksum(
        k * y[(i, k)] * data['profit'][k]
        for i, data in store_data.items()
        for k in data['k']
    ),
    GRB.MAXIMIZE
)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
